mapper.select:
select sum(T.AMOUNT) AMOUNT from PTL_SEC_POSITION_FLOW T
         where TRADE_ID IN (
         SELECT TRADE_ID FROM ETR_FINISH_STATUS 
         WHERE ENTRUST_ID = #{entrustId,jdbcType=VARCHAR} 
         AND TRADE_ID != #{entrustId,jdbcType=VARCHAR}

	 AND FINPROD_ID ='XN_PRODID999'


	AND FINPROD_ID !='XN_PRODID999'

)

	     select sum(finishAmt) from
	     (
	         select nvl(sum(decode(deal.ps,#{PS_T01},deal.trade_amt,deal.share_amt)),0) as finishAmt
			  from trd_product_temp_deal deal
			 inner join trd_product_temp_deal_add ad
			    on deal.trade_id = ad.trade_id
			 where ad.entrust_id = #{entrustId}
			   and ad.portfolio_id = #{portfolioId}
			   and deal.trade_status = #{TRADE_STATUS_01}
			   and deal.is_cancel = #{YES_OR_NO_N}


			 union all

             select nvl(sum(decode(deal.ps,#{PS_T01},deal.trade_amt,deal.share_amt)),0) as finishAmt
              from trd_product_deal deal
             inner join trd_product_deal_add ad
                on deal.trade_id = ad.trade_id
             where ad.entrust_id = #{entrustId}
               and ad.portfolio_id = #{portfolioId}
               and deal.trade_status = #{TRADE_STATUS_01}
               and deal.is_cancel = #{YES_OR_NO_N}

          )

select t1.ENTRUST_AMT - nvl(t2.PLEDGE_FACE_VALUE,0) shengYuEntrustAmt
from (select ENTRUST_AMT from ETR_ENTRUST where ENTRUST_ID=#{entrustId}) t1,
     (select sum(PLEDGE_FACE_VALUE) PLEDGE_FACE_VALUE from FIN_DEAL_TARGET where FINPROD_ID
                                                                                     in (select TRADE_ID from TRD_PRODUCT_DEAL where TRADE_STATUS = '01' and (IS_CANCEL = 'N' or IS_CANCEL is null)
                                                                                                                                 and TRADE_ID in (select TRADE_ID from TRD_PRODUCT_DEAL_ADD where ENTRUST_ID=#{entrustId}
             ))) t2

select nvl(sum(PLEDGE_NUMBER),0) from FIN_DEAL_PLEDGE where FINPROD_ID in (
    select TRADE_ID from TRD_PRODUCT_DEAL where TRADE_STATUS = '01' and (IS_CANCEL = 'N' or IS_CANCEL is null)
                                            and TRADE_ID in (select TRADE_ID from TRD_PRODUCT_DEAL_ADD where ENTRUST_ID = #{entrustId})
) and PLEDGE_FINPROD_ID=#{finprodId}

SELECT sum(AMOUNT) from (SELECT sum(T.AMOUNT) AMOUNT FROM PTL_CASH_POSITION_FLOW T WHERE ORDER_ID IN (SELECT ORDER_ID FROM stl_pay_temp_orders WHERE stl_pay_temp_orders.TRADE_ID IN (SELECT TRADE_ID FROM ETR_FINISH_STATUS WHERE ENTRUST_ID = #{entrustId,jdbcType=VARCHAR} AND TRADE_ID != #{entrustId,jdbcType=VARCHAR}) )
union all SELECT sum(T.AMOUNT) AMOUNT FROM PTL_CASH_POSITION_FLOW T WHERE ORDER_ID IN (SELECT TRADE_ID FROM ETR_FINISH_STATUS WHERE ENTRUST_ID = #{entrustId,jdbcType=VARCHAR} AND TRADE_ID != #{entrustId,jdbcType=VARCHAR})
)

